/// Every transaction read so far, from the files themselves.
///
/// THE FILES ARE THE STORE. `processed/` holds every statement that has been claimed, and parsing is
/// deterministic — so re-reading them cannot drift from a second copy, because there is no second
/// copy to drift from. The account comes from the PROFILE that matched, not from the filename, so a
/// Chase card and a Chase chequing export do not collapse onto one id.
/// Every transaction read so far, and every statement PERIOD the exports carried.
///
/// THE FILES ARE THE STORE. `processed/` holds every statement that has been claimed, and parsing is
/// deterministic — so re-reading them cannot drift from a second copy, because there is no second
/// copy to drift from. The account comes from the PROFILE that matched, not from the filename, so a
/// Chase card and a Chase chequing export do not collapse onto one id.
///
/// A file whose export carried a running balance yields a period, and a period is what lets
/// `reconcile` actually gate rather than being a type nothing exercises.
type ReadStatements = (Vec<crate::txn::Txn>, Vec<reconcile::StatementPeriod>, Vec<String>);

pub fn read_all_statements() -> Result<ReadStatements, String> {
    let mut txns = Vec::new();
    let mut periods = Vec::new();
    let mut notes = Vec::new();
    for dir in [inbox::processed_dir(), inbox::inbox_dir()].into_iter().flatten() {
        for f in inbox::scan(&dir)? {
            let Ok(text) = std::fs::read_to_string(&f.path) else { continue };
            match statement::parse_csv(&text) {
                Ok(p) => {
                    let id = statement::suggested_account_id(&p);
                    let lifted: Vec<crate::txn::Txn> = p
                        .txns
                        .iter()
                        .map(|row| crate::txn::Txn::from_row(row, &id, crate::money::Currency::USD))
                        .collect();
                    if let (Some(b), Some(first), Some(last)) = (p.period, lifted.first(), lifted.last()) {
                        periods.push(reconcile::usd_period(&id, &first.date, &last.date, b.opening, b.closing));
                    } else {
                        notes.push(format!("{}: no running balance, so this file cannot be reconciled — a fact about the export, not a failure", f.name));
                    }
                    txns.extend(lifted);
                    if !p.rejected.is_empty() {
                        notes.push(format!("{}: {} row(s) unread — every total below is short by them", f.name, p.rejected.len()));
                    }
                }
                Err(e) => notes.push(format!("{}: NOT READ — {e}", f.name)),
            }
        }
    }
    txns.sort_by(|a, b| a.date.cmp(&b.date));
    Ok((txns, periods, notes))
}

/// Everything the analysis verbs stand on, built once.
///
/// Six verbs need the same four things — the transactions, a ledger that says whether they were
/// checked, the position that follows, and the notes explaining what could not be read. Each of them
/// assembled it inline until there were four copies, and a fifth would have been the one where the
/// reconcile silently differed from the others.
pub struct Analysis {
    pub txns: Vec<crate::txn::Txn>,
    pub ledger: reconcile::ReconciledLedger,
    pub position: position::Position,
    pub notes: Vec<String>,
}

/// Read every claimed statement and derive the position from it.
///
/// A REAL RECONCILE WHEN THE EXPORTS CARRIED BALANCES, and an honest unverified ledger when they did
/// not — never a reconcile that quietly passed because nothing checked it.
pub fn analysis(as_of: &str) -> Result<Analysis, String> {
    let usd = crate::money::Currency::USD;
    let (accounts, _) = load_accounts();
    let stored = load_balances();
    let (txns, periods, mut notes) = read_all_statements()?;
    let through = txns.last().map(|t| t.date.clone()).unwrap_or_else(|| as_of.to_string());
    // The statements' own closing figures ARE balances, so an export alone is enough to answer — a
    // declared account no longer has to be told what it holds. What a person typed wins on the same
    // day; see `balance::prefer_observed`.
    let balances = balance::latest_each(&balance::prefer_observed(&stored, &balance::from_periods(&periods)));
    let ledger = if periods.is_empty() {
        reconcile::unverified_ledger(&txns, &through, "no export carried a running balance, so there is nothing to check the transactions against")?
    } else {
        let r = reconcile::reconcile(&txns, &periods);
        match r.ledger {
            Some(l) => l,
            None => {
                for p in &r.problems {
                    notes.push(format!("RECONCILE: {}", p.detail));
                }
                for u in &r.uncovered {
                    notes.push(format!("RECONCILE: {} on {} belongs to no statement period", u.description, u.date));
                }
                reconcile::unverified_ledger(&txns, &through, "the statements did NOT reconcile — see the notes below")?
            }
        }
    };
    let position = position::position(&ledger, &accounts, &balances, usd);
    Ok(Analysis { txns, ledger, position, notes })
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let json = args.iter().any(|a| a == "--json");
    let positional: Vec<&String> = positional_args(&args);
    match positional.first().map(|s| s.as_str()) {
        Some("parse") => {
            let path = positional
                .get(1)
                .ok_or_else(|| format!("usage: {prog} parse <file.csv> [--json]"))?;
            let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
            let p = statement::parse_csv(&text)?;
            if json {
                println!("{}", render_json(&p));
            } else {
                print!("{}", render_text(&p));
            }
            Ok(())
        }
        Some("start") => {
            let dir = inbox::inbox_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            std::fs::create_dir_all(&dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
            print!("{}", render_start(&dir));
            let waiting = inbox::scan(&dir)?;
            if !waiting.is_empty() {
                println!("Already waiting:");
                print!("{}", render_inbox(&waiting));
            }
            Ok(())
        }
        Some("inbox") => {
            let dir = inbox::inbox_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            let files = inbox::scan(&dir)?;
            if !args.iter().any(|a| a == "--ingest") {
                print!("{}", render_inbox(&files));
                if files.iter().any(|f| f.readable()) {
                    println!("  run `{prog} inbox --ingest` to read and claim them");
                }
                return Ok(());
            }
            let processed = inbox::processed_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            let at = session::now_iso();
            // Loaded ONCE and appended to as files are read, so two statements for the same account
            // do not both report it as undeclared.
            let (mut declared, _) = load_accounts();
            for f in &files {
                if !f.readable() {
                    println!("{} · SKIPPED, cannot tell which institution it is from", f.name);
                    continue;
                }
                let text = std::fs::read_to_string(&f.path).map_err(|e| format!("cannot read {}: {e}", f.name))?;
                match statement::parse_csv(&text) {
                    Ok(p) => {
                        print!("{}", render_text(&p));
                        // CLOSE THE LOOP. The file just told us an account exists; the registry is
                        // the only thing that can say what it IS, and nothing else will notice.
                        let id = statement::suggested_account_id(&p);
                        if account::undeclared(&declared, [id.as_str()]).is_empty() {
                            // already known
                        } else {
                            println!("  NOT DECLARED — nothing downstream can use these rows until it is:");
                            println!("    {}", declare_hint(&id, p.institution.name(), p.account_kind));
                            declared.push(Account {
                                id: id.clone(),
                                institution: p.institution.name().to_string(),
                                kind: p.account_kind,
                                currency: "USD".into(),
                                credit_limit: None,
                                apr_bps: None,
                                minimum_payment: None,
                                statement_day: None,
                                note: None,
                            });
                        }
                        // CLAIMED ONLY AFTER IT READ. A file moved out of the inbox on a parse that
                        // failed is a statement nobody will notice is missing.
                        let dest = inbox::claim(&f.path, &processed, &at)?;
                        println!("  claimed → {}", dest.display());
                    }
                    Err(e) => println!("{} · NOT READ: {e}\n  left in the inbox", f.name),
                }
            }
            Ok(())
        }
        Some("account") => {
            let (mut accounts, rejected) = load_accounts();
            match positional.get(1).map(|s| s.as_str()) {
                Some("set") => {
                    let mut raw = String::new();
                    std::io::Read::read_to_string(&mut std::io::stdin(), &mut raw)
                        .map_err(|e| format!("cannot read stdin: {e}"))?;
                    let v: serde_json::Value = serde_json::from_str(&raw).map_err(|e| format!("not JSON: {e}"))?;
                    let items = if v.is_array() { v.as_array().unwrap().clone() } else { vec![v] };
                    for item in &items {
                        account::upsert(&mut accounts, account::from_json(item)?);
                    }
                    save_accounts(&accounts)?;
                    println!("{} account(s) stored; {} known", items.len(), accounts.len());
                    Ok(())
                }
                Some("remove") => {
                    let id = positional.get(2).ok_or_else(|| format!("usage: {prog} account remove <id>"))?;
                    let before = accounts.len();
                    accounts.retain(|a| &a.id != *id);
                    if accounts.len() == before {
                        return Err(format!("{prog}: no account `{id}`"));
                    }
                    save_accounts(&accounts)?;
                    println!("removed {id}");
                    Ok(())
                }
                Some(other) if other != "list" => Err(format!("{prog}: unknown account command `{other}` — try list, set or remove")),
                _ => {
                    if json {
                        println!("{}", accounts_json(&accounts, &rejected));
                    } else {
                        print!("{}", account::render(&accounts));
                        for r in &rejected {
                            println!("  UNREADABLE ROW: {r}");
                        }
                    }
                    Ok(())
                }
            }
        }
        Some("balance") => {
            let (accounts, _) = load_accounts();
            let mut balances = load_balances();
