            let bps: f64 = flag_value(&args, "--costs").and_then(|v| v.parse().ok()).unwrap_or(10.0);

            let mut files: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
                .map_err(|e| format!("cannot read {}: {e}", dir.display()))?
                .filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("csv"))
                .collect();
            files.sort();
            if files.is_empty() {
                return Err(format!(
                    "no price data in {}\n\n  Drop a daily CSV per symbol, named for it — AAPL.csv. Both layouts are read:\n    Date,Open,High,Low,Close,Volume                  (stooq — declared UNADJUSTED)\n    Date,Open,High,Low,Close,Adj Close,Volume        (yahoo — the adjusted close is used)\n\n  Adjusted data is worth the trouble: in an unadjusted series a 2-for-1 split is a -50%\n  day, and a strategy that buys drops will find a great many of them.",
                    dir.display()
                ));
            }

            let mut reports: Vec<(String, Vec<crate::evaluate::Evaluation>, Vec<String>)> = Vec::new();
            for f in files {
                let symbol = f.file_stem().and_then(|x| x.to_str()).unwrap_or("?").to_uppercase();
                if want.as_ref().is_some_and(|w| *w != symbol) {
                    continue;
                }
                let text = std::fs::read_to_string(&f).map_err(|e| format!("cannot read {}: {e}", f.display()))?;
                let parsed = match bars::parse_csv(&text, &symbol, "file") {
                    Ok(p) => p,
                    Err(e) => {
                        reports.push((symbol, Vec::new(), vec![format!("NOT READ — {e}")]));
                        continue;
                    }
                };
                let mut notes: Vec<String> = Vec::new();
                if !parsed.rejected.is_empty() {
                    notes.push(format!("{} row(s) unread — the series is short by them and a gap is something a strategy steps over", parsed.rejected.len()));
                }
                // CHECK FIRST, and fall back to an explicitly unverified series rather than
                // refusing outright — a system that refuses everything is one nobody uses, and the
                // caveat travels into every result either way.
                let checked = series::check_series(&parsed.bars, parsed.meta.clone(), &series::CheckOptions::default());
                let s = match checked.series {
                    Some(s) => s,
                    None => {
                        for p in checked.problems.iter().take(8) {
                            notes.push(format!("{} at {}: {}", p.kind.label(), p.at, p.detail));
                        }
                        if checked.problems.len() > 8 {
                            notes.push(format!("... and {} more series problem(s)", checked.problems.len() - 8));
                        }
                        series::unverified_series(&parsed.bars, parsed.meta, "the series did not pass its checks — see the notes")?
                    }
                };
                let battery = signals::default_battery();
                let refs: Vec<&dyn crate::evaluate::Signal> = battery.iter().map(|b| b.as_ref()).collect();
                let opts = crate::evaluate::EvalOptions {
                    costs: crate::evaluate::Costs { per_turn: bps / 10_000.0 },
                    ..crate::evaluate::EvalOptions::default()
                };
                reports.push((symbol, crate::evaluate::evaluate_all(&s, &refs, &opts), notes));
            }

            if reports.is_empty() {
                return Err(format!("no price data for {}", want.unwrap_or_default()));
            }
            if json {
                println!("{}", serde_json::json!({
                    "costsBps": bps,
                    "symbols": reports.iter().map(|(sym, evs, notes)| serde_json::json!({
                        "symbol": sym, "notes": notes,
                        "results": evs.iter().map(|e| serde_json::json!({
                            "signal": e.signal, "verdict": e.verdict.label(), "why": e.why,
                            "net": e.net.map(|s| serde_json::json!({"totalReturn": s.total_return, "cagr": s.cagr, "sharpe": s.sharpe, "maxDrawdown": s.max_drawdown, "periods": s.periods})),
                            "gross": e.gross.map(|s| s.total_return),
                            "benchmark": e.benchmark.map(|s| s.total_return),
                            "outOfSample": e.out_of_sample.map(|s| s.total_return),
                            "costDrag": e.cost_drag, "trades": e.trades, "turnover": e.turnover,
                            "tStat": e.t_stat, "tRequired": e.t_required, "caveats": e.caveats,
                        })).collect::<Vec<_>>(),
                    })).collect::<Vec<_>>(),
