                    };
                    if invoices.iter().any(|i| i.number == number) {
                        return Err(format!("{number} already exists — an invoice number is the reference a payer quotes, so reusing one makes two debts indistinguishable"));
                    }
                    let minor = crate::money::parse_minor(&raw).map_err(|e| format!("{raw}: {e}"))?;
                    if minor <= 0 {
