                        println!("Revenue {} → {}\n", r.from, r.to);
                        println!("  Cash basis     {:>12}   what ARRIVED in the window", crate::money::format_minor(r.cash_basis.minor));
                        println!("  Accrual basis  {:>12}   what was INVOICED in it\n", crate::money::format_minor(r.accrual_basis.minor));
                        println!("  {}", r.note);
                    }
                    Ok(())
                }
                Some(other) => Err(format!("{prog} invoice: unknown subcommand `{other}` — try new, write-off or revenue")),
                None => {
                    let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
                    // An unreadable statement store must not silently become "nothing arrived", so
                    // the failure is carried into the output rather than swallowed into an empty list.
                    let (credits, read_note) = match analysis(&as_of) {
                        Ok(a) => (a.txns, None),
                        Err(e) => (Vec::new(), Some(format!("no statement could be read ({e}), so NOTHING below is matched — every invoice reads as unpaid whether it is or not"))),
                    };
                    let mut m = invoice::match_payments(&invoices, &credits, &invoice::MatchOptions::default());
                    if let Some(n) = read_note {
                        m.notes.insert(0, n);
                    }
                    let settlements = invoice::settle(&invoices, &m, usd);
                    let buckets = invoice::age(&settlements, &invoices, &as_of, usd);
                    // A pricing that ERRORS (a cross-state sale, say) must not take the ledger down
                    // with it — the money owed is still the money owed. It becomes a note.
                    let mut priced: Vec<invoice::Priced> = Vec::new();
                    if let Some(seller) = load_place() {
                        for i in &invoices {
                            match invoice::price(i, &seller, jurisdiction::RATES, jurisdiction::PLACES, &as_of) {
                                Ok(p) => priced.push(p),
                                Err(e) => m.notes.push(format!("{}: {e}", i.number)),
                            }
                        }
                    } else if !invoices.is_empty() {
                        m.notes.push("nowhere is set, so no invoice below shows tax — `bsc fin where set <place>`".to_string());
                    }
                    if json {
                        println!("{}", serde_json::json!({
                            "asOf": as_of,
                            "invoices": settlements.iter().map(|s| serde_json::json!({
                                "number": s.invoice,
                                "client": s.client,
                                "billedMinor": s.billed.minor,
                                "receivedMinor": s.received.minor,
                                "outstandingMinor": s.outstanding.minor,
                                "state": s.state.label(),
                            })).collect::<Vec<_>>(),
                            "ageing": buckets.iter().map(|b| serde_json::json!({
                                "bucket": b.label,
                                "totalMinor": b.total.minor,
                                "invoices": b.invoices,
                            })).collect::<Vec<_>>(),
                            "matched": m.matched.iter().map(|p| serde_json::json!({
                                "invoice": p.invoice,
                                "date": p.date,
                                "amountMinor": p.amount.minor,
                                "confidence": p.confidence.label(),
                                "evidence": p.evidence,
                            })).collect::<Vec<_>>(),
                            "ambiguous": m.ambiguous.iter().map(|a| serde_json::json!({
                                "date": a.date,
                                "amountMinor": a.amount.minor,
                                "description": a.description,
                                "candidates": a.candidates,
                            })).collect::<Vec<_>>(),
                            "unexplained": m.unexplained.iter().map(|t| serde_json::json!({
                                "date": t.date,
                                "description": t.description,
                                "amountMinor": t.amount.minor,
                            })).collect::<Vec<_>>(),
                            "tax": priced.iter().map(|p| serde_json::json!({
                                "invoice": p.invoice,
                                "netMinor": p.net.minor,
                                "totalMinor": p.total.map(|t| t.minor),
                                "outcome": (match &p.tax {
                                    invoice::TaxOutcome::Charged { .. } => "charged",
                                    invoice::TaxOutcome::None { .. } => "none",
                                    invoice::TaxOutcome::Undetermined { .. } => "undetermined",
                                }),
                                "taxMinor": (match &p.tax { invoice::TaxOutcome::Charged { amount, .. } => Some(amount.minor), _ => None }),
                                "bps": (match &p.tax { invoice::TaxOutcome::Charged { bps, .. } => Some(*bps), _ => None }),
                                "detail": (match &p.tax {
                                    invoice::TaxOutcome::Charged { sources, .. } => sources.join("; "),
                                    invoice::TaxOutcome::None { reason, source } => format!("{reason} — {source}"),
                                    invoice::TaxOutcome::Undetermined { what, where_to } => format!("{what} — {where_to}"),
                                }),
                            })).collect::<Vec<_>>(),
                            "rejected": rejected,
                            "notes": m.notes,
                        }));
                    } else {
                        print!("{}", render_invoices(&settlements, &buckets, &m, &priced, &as_of));
                    }
                    Ok(())
                }
            }
        }
        Some("where") => {
            let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
            let places = jurisdiction::PLACES;
            let rates = jurisdiction::RATES;
            match positional.get(1).map(|s| s.as_str()) {
                Some("places") => {
                    // A prefix, because fifty-odd rows is a list you scroll past rather than read.
                    let prefix = positional.get(2).map(|s| s.as_str()).unwrap_or("");
                    let places: Vec<&jurisdiction::Place> = places.iter().filter(|p| p.id.starts_with(prefix)).collect();
                    if places.is_empty() {
                        return Err(format!("nothing under `{prefix}` — try `{prog} where places us`"));
                    }
                    if json {
                        println!("{}", serde_json::json!({
                            "places": places.iter().map(|p| serde_json::json!({
                                "id": p.id,
                                "name": p.name,
                                "level": p.level.label(),
                                "parent": p.parent,
                                // What is actually KNOWN about it, so a caller does not read the
                                // presence of a place as the presence of a rate.
                                "coverage": jurisdiction::coverage(jurisdiction::RATES, jurisdiction::SUPPLY_RULES, jurisdiction::OBLIGATIONS, jurisdiction::PLACES, p.id, &as_of).label(),
                            })).collect::<Vec<_>>(),
                        }));
                    } else {
                        println!("Places\n");
                        for p in &places {
                            // What RESOLVES here, following the chain — Duluth declares no rate of
                            // its own and inherits every one that applies to it.
                            let cov = jurisdiction::coverage(jurisdiction::RATES, jurisdiction::SUPPLY_RULES, jurisdiction::OBLIGATIONS, jurisdiction::PLACES, p.id, &as_of);
                            println!("  {:<26} {:<10} {:<24} {}", p.id, p.level.label(), p.name, cov.label());
                        }
                        println!("\n  The last column is what RESOLVES there, inherited rates included. `duties only`");
                        println!("  means the federal obligations reach it and nothing else is recorded, so it answers");
                        println!("  NOT KNOWN and says where to look. Filling one in is data, not a code change.");
                    }
                    Ok(())
                }
                Some("sources") => {
                    let src = jurisdiction::sources(rates, jurisdiction::OBLIGATIONS);
                    if json {
                        println!("{}", serde_json::json!({
                            "checkedByAPerson": false,
                            "sources": src.iter().map(|(p, s)| serde_json::json!({ "place": p, "source": s })).collect::<Vec<_>>(),
                        }));
                    } else {
                        println!("Every figure, and where it came from. NONE has been checked by a person.\n");
                        for (p, s) in &src {
                            println!("  {:<26} {}", p, s);
                        }
                    }
                    Ok(())
                }
                Some("set") => {
                    let id = positional.get(2).ok_or_else(|| format!("usage: {prog} where set <place>   # e.g. us/ga/gwinnett/duluth"))?;
                    // REFUSE AN UNKNOWN PLACE rather than storing it. A stored id that resolves to
                    // nothing would make every later answer an error with no obvious cause.
                    jurisdiction::chain(places, id)?;
                    save_place(id)?;
                    println!("where: {id}");
                    Ok(())
                }
                Some("taxable") => {
                    let id = load_place().ok_or_else(|| format!("nowhere is set — run `{prog} where set us/ga/gwinnett/duluth` first"))?;
                    let raw = positional.get(2).ok_or_else(|| format!("usage: {prog} where taxable <service|good|digital|saas>"))?;
                    let supply = match raw.as_str() {
                        "service" => jurisdiction::Supply::ProfessionalService,
                        "good" => jurisdiction::Supply::TangibleGood,
                        "digital" => jurisdiction::Supply::DigitalProduct,
                        "saas" => jurisdiction::Supply::SoftwareAsService,
                        other => return Err(format!("`{other}` is not a supply kind — one of service, good, digital, saas")),
                    };
                    let t = jurisdiction::taxability(rates, places, &id, supply, &as_of)?;
                    if json {
                        println!("{}", serde_json::json!({
                            "place": id,
                            "supply": supply.label(),
                            "asOf": as_of,
                            "verdict": (match &t {
                                jurisdiction::Taxability::Taxable { .. } => "taxable",
                                jurisdiction::Taxability::Exempt { .. } => "exempt",
                                jurisdiction::Taxability::Unknown { .. } => "unknown",
                            }),
                            "bps": (match &t { jurisdiction::Taxability::Taxable { bps, .. } => Some(*bps), _ => None }),
                            "detail": (match &t {
                                jurisdiction::Taxability::Taxable { sources, .. } => sources.join("; "),
                                jurisdiction::Taxability::Exempt { reason, source } => format!("{reason} — {source}"),
                                jurisdiction::Taxability::Unknown { what_to_check, where_to_check } => format!("{what_to_check} — {where_to_check}"),
                            }),
                        }));
                    } else {
                        println!("{} in {id}, as of {as_of}\n", supply.label());
                        match &t {
                            jurisdiction::Taxability::Taxable { bps, sources } => {
                                println!("  TAXABLE at {}", format_bps(*bps));
                                for s in sources {
                                    println!("    source: {s}");
                                }
                            }
                            jurisdiction::Taxability::Exempt { reason, source } => {
                                println!("  NOT TAXABLE — {reason}");
                                println!("    source: {source}");
                            }
                            jurisdiction::Taxability::Unknown { what_to_check, where_to_check } => {
                                // Not zero. Not exempt. Unknown, said out loud.
                                println!("  NOT KNOWN — {what_to_check}");
                                println!("    check: {where_to_check}");
                            }
                        }
                    }
                    Ok(())
                }
                Some(other) => Err(format!("{prog} where: unknown subcommand `{other}` — try set, taxable, places or sources")),
                None => {
                    let Some(id) = load_place() else {
                        println!("Nowhere is set yet.\n");
                        println!("  bsc fin where set us/ga/gwinnett/duluth");
                        println!("  bsc fin where places        # what is seeded\n");
                        println!("  Until then nothing can say what you owe, what you must register for, or");
                        println!("  whether an invoice carries tax — and guessing any of those is worse than");
                        println!("  the question staying open.");
                        return Ok(());
                    };
                    let chain = jurisdiction::chain(places, &id)?;
                    let obligations = jurisdiction::obligations_for(jurisdiction::OBLIGATIONS, places, &id)?;
                    let sales = jurisdiction::combined(rates, places, &id, jurisdiction::RateKind::SalesTax, &as_of);
                    let income = jurisdiction::rates_at(rates, places, &id, jurisdiction::RateKind::IncomeTax, &as_of)?;
                    if json {
                        println!("{}", serde_json::json!({
                            "place": id,
                            "asOf": as_of,
                            "checkedByAPerson": false,
                            "chain": chain.iter().map(|p| serde_json::json!({ "id": p.id, "name": p.name, "level": p.level.label() })).collect::<Vec<_>>(),
                            "salesTaxBps": sales.as_ref().ok().map(|(b, _)| *b),
                            "salesTaxRefusal": sales.as_ref().err(),
                            "incomeTax": income.iter().map(|r| serde_json::json!({
                                "place": r.place, "bps": r.bps, "through": r.to, "source": r.source,
                            })).collect::<Vec<_>>(),
                            "obligations": obligations.iter().map(|o| serde_json::json!({
                                "place": o.place,
                                "name": o.name,
                                "what": o.what,
                                "authority": o.authority,
                                "costMinor": o.cost_minor,
                                "nextDue": jurisdiction::next_due(o.cadence, &as_of),
                                "requiredWhen": o.required_when,
                                "source": o.source,
                            })).collect::<Vec<_>>(),
                        }));
                    } else {
                        print!("{}", render_where(&chain, &obligations, &sales, &income, &as_of));
                    }
                    Ok(())
                }
            }
        }
        Some("hurdle") => {
            let usd = crate::money::Currency::USD;
            let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
            let pct = |flag: &str| -> Result<Option<i64>, String> {
                match flag_value(&args, flag) {
                    None => Ok(None),
                    Some(raw) => Ok(Some(crate::money::parse_minor(&raw).map_err(|e| format!("{flag} {raw}: {e}"))?)),
                }
            };
            // THE EXPECTATION IS AN INPUT AND IT IS NEVER DEFAULTED. A number invented here would
            // fabricate the entire comparison, and it would be believed.
            let expect_bps = pct("--expect")?.ok_or_else(|| {
                format!("--expect is required: what annual PRE-TAX return do you expect, as a percent? This tool will not supply it — a figure invented here would decide the whole comparison. And do NOT paste a backtested number from `{prog} backtest`: those are selected from many trials, and `{prog} simulate` shows the best of 200 worthless signals on noise reaching +45.9%.")
            })?;
            let tax_bps = pct("--tax")?.ok_or_else(|| "--tax is required: what rate would gains be taxed at? Debt paydown is tax-free, so this is what sets the bar.".to_string())?;
            let source = flag_value(&args, "--source").ok_or_else(|| {
                "--source is required: say where the expectation came from, in a few words. A number with no provenance is a guess wearing a decimal point, and in six months you will not remember which it was.".to_string()
            })?;
            let e = hurdle::Expectation {
                annual_return_bps: expect_bps,
                tax_bps,
                risk_premium_bps: pct("--premium")?.unwrap_or(0),
                source,
            };
            let target_months = flag_value(&args, "--buffer-months").map(|r| r.parse::<i64>().map_err(|_| "--buffer-months must be a whole number".to_string())).transpose()?.unwrap_or(3);
            let deductible: Vec<String> = args
                .windows(2)
                .filter(|w| w[0] == "--deductible")
                .map(|w| w[1].clone())
                .collect();

            let a = analysis(&as_of)?;
            let (txns, p) = (a.txns, a.position);
            let found = recurring::detect_recurring(&txns, &recurring::DetectOptions { min_occurrences: 2, outflows_only: true, as_of: &as_of });
            let sp = spending::analyse_spending(&a.ledger, Some(&p), &found, usd, &spending::SpendingOptions::default());
            let monthly_need = crate::money::money(sp.fixed_monthly.minor.abs() + sp.variable_monthly.minor.abs(), usd);

            let debts: Vec<hurdle::Debt> = p
                .accounts
                .iter()
                .filter_map(|ap| {
                    ap.owed.map(|owed| hurdle::Debt {
                        account: ap.account.clone(),
                        balance: owed,
                        // A rate this does not know stays None. `apr` is already Option for the same
                        // reason, and collapsing it to 0 here would undo that.
                        apr_bps: ap.apr.map(|r| (r * 10_000.0).round() as i64),
                        deductible: deductible.contains(&ap.account),
                    })
                })
                .collect();

            let b = hurdle::buffer(p.liquid, monthly_need, target_months)?;
            let l = hurdle::ladder(&debts, &e)?;
            let next = hurdle::next_dollar(&b, &l);
            if json {
                println!("{}", serde_json::json!({
                    "asOf": as_of,
                    "expectation": { "annualReturnBps": e.annual_return_bps, "taxBps": e.tax_bps, "riskPremiumBps": e.risk_premium_bps, "source": e.source },
                    "buffer": { "liquidMinor": b.liquid.minor, "monthlyNeedMinor": b.monthly_need.minor, "monthsHeldTenths": b.months_held_tenths, "targetMonths": b.target_months, "shortfallMinor": b.shortfall.minor, "met": b.met },
                    "ladder": l.iter().map(|h| serde_json::json!({
                        "account": h.account,
                        "owedMinor": h.balance.minor,
                        "aprBps": h.apr_bps,
                        "requiredBps": h.required_bps,
                        "barBps": h.bar_bps,
                        "annualCostMinor": h.annual_cost.map(|c| c.minor),
                        "verdict": h.verdict.label(),
                    })).collect::<Vec<_>>(),
                    "nextDollar": (match &next {
                        hurdle::NextDollar::BuildBuffer { .. } => "build-buffer",
                        hurdle::NextDollar::FindOutTheRate { .. } => "find-out-the-rate",
                        hurdle::NextDollar::PayDebt { .. } => "pay-debt",
                        hurdle::NextDollar::Invest => "invest",
                        hurdle::NextDollar::NothingToWeigh => "nothing-to-weigh",
                    }),
                    "notes": a.notes,
                }));
            } else {
                print!("{}", render_hurdle(&e, &b, &l, &next, &as_of));
                for n in &a.notes {
                    println!("  · {n}");
                }
            }
            Ok(())
        }
        Some("tax") => {
            let usd = crate::money::Currency::USD;
            let year: i32 = flag_value(&args, "--year")
                .ok_or_else(|| format!("usage: {prog} tax --year <YYYY> --status <single|joint|separate|head>"))?
                .parse()
                .map_err(|_| "--year must be a four-digit year".to_string())?;
            // NEITHER of these is defaulted. A year decides the wage base and a status moves the
            // Medicare surcharge threshold by $125,000, so a wrong default is a wrong return.
            let status_raw = flag_value(&args, "--status").ok_or_else(|| {
                format!("--status is required — it moves the Medicare surcharge threshold by $125,000, so it is not something to default. One of: {}",
                    taxyear::FilingStatus::ALL.iter().map(|s| s.key()).collect::<Vec<_>>().join(", "))
            })?;
            let status = taxyear::FilingStatus::parse(&status_raw)
                .ok_or_else(|| format!("`{status_raw}` is not a filing status — one of {}", taxyear::FilingStatus::ALL.iter().map(|s| s.key()).collect::<Vec<_>>().join(", ")))?;
            let p = taxyear::params_for(taxyear::YEARS, year)?;

            let expenses = match flag_value(&args, "--expenses") {
                None => None,
                Some(raw) => Some(crate::money::money(crate::money::parse_minor(&raw).map_err(|e| format!("--expenses {raw}: {e}"))?, usd)),
            };
            // A percentage in, basis points held. `--income-rate 22` is 22%, not 22 basis points.
            let income_bps = match flag_value(&args, "--income-rate") {
                None => None,
                Some(raw) => Some(crate::money::parse_minor(&raw).map_err(|e| format!("--income-rate {raw}: {e}"))?),
            };

            let (from, to) = (format!("{year}-01-01"), format!("{year}-12-31"));
            let (invoices, rejected) = load_invoices();
            for r in &rejected {
                eprintln!("invoices.json: {r}");
            }
            // Revenue is CASH BASIS — what arrived — because that is what a sole proprietor almost
            // always files on, and `bsc fin invoice revenue` reports both if the other is wanted.
            let credits = analysis(&to).map(|a| a.txns).unwrap_or_default();
            let m = invoice::match_payments(&invoices, &credits, &invoice::MatchOptions::default());
            let rev = invoice::revenue(&invoices, &m, &from, &to, usd);

            let y = taxyear::assemble(year, status, rev.cash_basis, expenses, income_bps, &p);
            let harbour = taxyear::safe_harbour(&y.se);
            if json {
                println!("{}", serde_json::json!({
                    "year": y.year,
                    "status": y.status.key(),
                    "revenueMinor": y.revenue.minor,
                    "accrualRevenueMinor": rev.accrual_basis.minor,
                    "expensesMinor": y.expenses.minor,
                    "expensesDeclared": (y.expense_basis == taxyear::ExpenseBasis::Declared),
                    "netProfitMinor": y.net_profit.minor,
                    "selfEmployment": {
                        "netEarningsMinor": y.se.net_earnings.minor,
                        "socialSecurityMinor": y.se.social_security.minor,
                        "medicareMinor": y.se.medicare.minor,
                        "additionalMedicareMinor": y.se.additional_medicare.minor,
                        "totalMinor": y.se.total.minor,
                        "deductibleHalfMinor": y.se.deductible_half.minor,
                        "wageBaseBound": y.se.cap_bound,
                    },
                    "setAsideMinor": y.set_aside.map(|a| a.minor),
                    "safeHarbourMinor": harbour.0.minor,
                    "incomeTaxComputed": false,
                    "checkedByAPerson": false,
                    "wageBaseSource": p.source,
                    "notes": y.se.notes.iter().chain(y.notes.iter()).collect::<Vec<_>>(),
                }));
            } else {
                print!("{}", render_tax(&y, &p, harbour));
                // The evidence for the judgement this cannot make. Shown AFTER the report so it
                // reads as candidates to sort through, never as a deduction already taken.
                if y.expense_basis == taxyear::ExpenseBasis::Absent {
                    if let Ok(a) = analysis(&to) {
                        let found = recurring::detect_recurring(&a.txns, &recurring::DetectOptions { min_occurrences: 2, outflows_only: true, as_of: &to });
                        let sp = spending::analyse_spending(&a.ledger, Some(&a.position), &found, usd, &spending::SpendingOptions::default());
                        let top = spending::top_categories(&sp, 8);
                        if !top.is_empty() {
                            println!("\n  Candidates for --expenses, from your statements. NONE of this is claimed:");
                            for c in top {
                                println!("    {:<28} {:>12}", clip(c.category, 27), crate::money::format_minor(c.total.minor.abs()));
                            }
                            println!("    Business or personal is a judgement no bank line can make, and this has not");
                            println!("    tried. Add up the ones that are genuinely business costs and pass the total.");
                        }
                    }
                }
            }
            Ok(())
        }
        Some("session") => {
            let mut states = load_states();
            let connectors: Vec<&str> = inbox::KNOWN.to_vec();
            match positional.get(1).map(|s| s.as_str()) {
                Some(id) if args.iter().any(|a| a == "--established") => {
                    if !connectors.contains(&id) {
                        return Err(format!("{prog}: `{id}` is not a known institution — try one of: {}", connectors.join(", ")));
                    }
                    let mut state = session::state_for(&states, id);
                    session::established(&mut state, &session::now_iso());
                    session::upsert(&mut states, state);
                    save_states(&states)?;
                    println!("{id} · session recorded — unattended fetches may reuse it until it ages out");
                    Ok(())
                }
                Some(id) => Err(format!(
                    "usage: {prog} session {id} --established  # after signing in by hand"
                )),
                None => {
                    print!("{}", render_sessions(&states, &connectors, &session::now_iso()));
                    Ok(())
                }
            }
        }
        // The offer is BUILT FROM `COMMANDS`, not typed out beside it. A hand-written list is a
        // second place to remember, and the test over `COMMANDS` caught it going stale the first
        // time a verb was added — so the fix is to remove the second place rather than update it.
        Some(other) => Err(format!("{prog}: unknown command `{other}` — try {}", verb_list(prog))),
        None => Err(format!(
            "usage: {prog} <{}>",
            COMMANDS.iter().map(|c| c.name).collect::<Vec<_>>().join("|")
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::statement::{Institution, Rejected, Txn};

    fn inv_fixture() -> (Vec<invoice::Invoice>, Vec<crate::txn::Txn>) {
        // SYNTHETIC. Two invoices at the same amount to the same client — the case a reference
        // resolves and nothing else can.
        let usd = crate::money::usd;
        let invoices = vec![
            invoice::Invoice::new("INV-014", "ACME", "2026-06-01", "2026-06-15", usd(240_000), "work"),
            invoice::Invoice::new("INV-015", "ACME", "2026-06-02", "2026-07-02", usd(240_000), "work"),
            invoice::Invoice::new("INV-016", "BETA", "2026-06-03", "2026-07-03", usd(90_000), "work"),
        ];
        let credit = |date: &str, d: &str, m: i64| crate::txn::Txn {
            account: "chk".into(),
