    #[test]
    fn a_flags_value_is_never_read_as_a_positional_argument() {
        let v = |xs: &[&str]| {
            let owned: Vec<String> = xs.iter().map(|x| (*x).to_string()).collect();
            positional_args(&owned).into_iter().cloned().collect::<Vec<String>>()
        };
        // THE BUG: the date landed where the subcommand goes and was reported as an unknown one.
        assert_eq!(v(&["invoice", "--as-of", "2026-07-10"]), vec!["invoice"]);
        // A boolean flag consumes nothing, so the token after it is still positional.
        assert_eq!(v(&["parse", "--json", "file.csv"]), vec!["parse", "file.csv"]);
        assert_eq!(v(&["inbox", "--ingest"]), vec!["inbox"]);
        // A value flag before the positionals no longer shifts them.
        assert_eq!(v(&["invoice", "new", "INV-1", "ACME", "10.00", "--due", "2026-07-01"]), vec!["invoice", "new", "INV-1", "ACME", "10.00"]);
        assert_eq!(v(&["--as-of", "2026-07-10", "invoice", "new"]), vec!["invoice", "new"]);
    }

    /// The list of presence-flags can only go stale in ONE direction, and this is that direction.
    ///
    /// A VALUE flag missing from `BOOLEAN_FLAGS` is handled correctly by default. A PRESENCE flag
    /// missing from it silently eats the token after it — which is the bug this whole helper exists
    /// to fix, reintroduced by adding a verb. So the source is scanned for the shape that tests a
    /// flag's presence (`a == "--x"`) and every hit must be declared.
    #[test]
    fn every_presence_flag_in_this_module_is_declared_boolean() {
        let src = include_str!(concat!(env!("OUT_DIR"), "/crate.rs"));
        let mut found: Vec<String> = Vec::new();
        for (i, _) in src.match_indices("== \"--") {
            // Only the PRESENCE idiom — `args.iter().any(|a| a == "--x")`. The pair form
            // `.filter(|(f, _)| *f == "--promo")` matches a flag that DOES take a value, so
            // requiring `.any(` in the run-up is what separates the two rather than a deny-list.
            // A COMMENT IS NOT CODE — including this test's own description of the shape it looks
            // for, which is what it matched on the first run.
            let line_start = src[..i].rfind('\n').map_or(0, |n| n + 1);
            if src[line_start..i].trim_start().starts_with("//") {
                continue;
            }
            let back = &src[i.saturating_sub(24)..i];
            if !back.contains(".any(") {
                continue;
            }
            let rest = &src[i + "== \"--".len()..];
            let Some(end) = rest.find('"') else { continue };
            let flag = format!("--{}", &rest[..end]);
            if !found.contains(&flag) {
                found.push(flag);
            }
        }
        // ASSERT THE POPULATION. A scanner that quietly stopped matching would find nothing, and
        // nothing reads as a pass — which is the failure this repo keeps getting caught by.
        assert!(found.len() >= 5, "the scanner found only {found:?} — it has stopped matching, which is not the same as there being no offenders");
        let undeclared: Vec<&String> = found.iter().filter(|f| !BOOLEAN_FLAGS.contains(&f.as_str())).collect();
        assert!(
            undeclared.is_empty(),
            "these flags are tested for PRESENCE but are not in BOOLEAN_FLAGS, so each one eats the token after it: {undeclared:?}"
        );
    }

    #[test]
    fn duluth_renders_its_stack_its_components_and_who_to_file_with() {
        let places = jurisdiction::PLACES;
        let id = "us/ga/gwinnett/duluth";
        let chain = jurisdiction::chain(places, id).expect("seeded");
        let obs = jurisdiction::obligations_for(jurisdiction::OBLIGATIONS, places, id).expect("seeded");
        let sales = jurisdiction::combined(jurisdiction::RATES, places, id, jurisdiction::RateKind::SalesTax, "2026-09-04");
        let income = jurisdiction::rates_at(jurisdiction::RATES, places, id, jurisdiction::RateKind::IncomeTax, "2026-09-04").expect("resolvable");
        let out = render_where(&chain, &obs, &sales, &income, "2026-09-04");

        // The stack reads outermost-in, the way an address does.
        assert!(out.starts_with("United States › Georgia › Gwinnett County › Duluth"), "{out}");
        // The combined rate AND what it is made of — 4% state plus 2% county is the check a person
        // can actually perform against a rate chart.
        assert!(out.contains("6.00%"), "{out}");
        assert!(out.contains("us/ga/gwinnett 2.00%") && out.contains("us/ga 4.00%"), "{out}");
        // Georgia's income rate has LAPSED for this date, so the line says so rather than showing
        // last year's number. This is the behaviour the whole module exists for.
        assert!(income.is_empty());
        assert!(out.contains("income tax       NOT KNOWN"), "{out}");
        // The city licence is present with an authority to call.
        assert!(out.contains("Occupational tax certificate"), "{out}");
        assert!(out.contains("City of Duluth"), "{out}");
        // And the standing caveat is not optional.
        assert!(out.contains("NOTHING HERE HAS BEEN CHECKED"), "{out}");
        assert!(out.contains("not\n  tax advice"), "{out}");
    }

