        assert!(out.contains("YOUR number and not this tool's"), "{out}");
        assert!(out.contains("long-run index return, my own reading"), "the provenance is printed, not just stored: {out}");
        // A zero risk premium is CALLED OUT rather than passing as a considered choice.
        assert!(out.contains("treats a CERTAIN return and an uncertain one as equal"), "{out}");
        // The gross-up is visible: 24.99% tax-free needs 33.32% pre-tax.
        assert!(out.contains("24.99%") && out.contains("33.32%"), "{out}");
        // And the unknown rate is named as unknown, never as a number.
        assert!(out.contains("RATE UNKNOWN"), "{out}");
        assert!(!out.contains("mystery      1000.00     0.00%"), "an unknown rate must never render as 0%: {out}");
    }

