    #[test]
    fn the_session_report_distinguishes_your_turn_from_something_broke() {
        // One is the design working as intended; the other is something to go and look at. Printing
        // both as "failed" would make the normal case alarming and bury the real one.
        let now = "2026-07-01T12:00:00Z";
        let blocked = SessionState {
            connector: "chase".into(),
            attempts: vec![crate::session::Attempt { at: now.into(), outcome: crate::session::Outcome::Auth }],
            ..Default::default()
        };
        let fresh = SessionState { connector: "discover".into(), session_since: Some(now.into()), ..Default::default() };
        let out = render_sessions(&[blocked, fresh], &["chase", "discover", "capital-one"], now);
        assert!(out.contains("chase · BLOCKED"), "{out}");
        assert!(out.contains("discover · ready"), "{out}");
        assert!(out.contains("capital-one · your turn"), "{out}");
        assert!(!out.contains("capital-one · BLOCKED"), "{out}");
    }

