    #[test]
    fn every_documented_command_is_one_run_actually_accepts() {
        // A COMMANDS entry that `run` rejects is help advertising a verb that does not exist, which
        // is worse than no help at all.
        for c in COMMANDS {
            // A verb may legitimately fail on its own arguments; what it must never do is come back
            // as unrecognised, which would be help advertising something that does not exist.
            if let Err(e) = run(args(&[c.name]), "bsc fin") {
                assert!(!e.contains("unknown command"), "help lists `{}` but run rejects it: {e}", c.name);
            }
        }
        assert!(!COMMANDS.is_empty());
    }

    #[test]
    fn a_minor_unit_amount_is_not_printed_beside_its_own_formatted_column() {
        // "chase minimum — 6000 due" next to a formatted "60.00" reads as two numbers a hundred
        // times apart. The suffix goes; everything else is left exactly alone.
        assert_eq!(trim_minor_suffix("chase minimum — 6000 due"), "chase minimum");
        assert_eq!(trim_minor_suffix("RENT LANDLORD LLC — 120000 due"), "RENT LANDLORD LLC");
        // An em-dash that is part of the sentence must NOT be cut — this one nearly was.
        assert_eq!(trim_minor_suffix("chase — ask for a rate reduction"), "chase — ask for a rate reduction");
        assert_eq!(trim_minor_suffix("storeco — hardship arrangement, BEFORE a payment is missed"), "storeco — hardship arrangement, BEFORE a payment is missed");
        assert_eq!(trim_minor_suffix("move 300000 from visa to newbank"), "move 300000 from visa to newbank");
        assert_eq!(trim_minor_suffix("a — b due"), "a — b due", "only DIGITS are an amount");
        assert_eq!(trim_minor_suffix("a —  due"), "a —  due", "an empty number is not one");
        assert_eq!(trim_minor_suffix(""), "");
    }

    #[test]
    fn a_merchant_name_with_an_accent_does_not_kill_the_renderer() {
        // `&s[..22]` panics when byte 22 lands mid-character. Every one of these is longer than 22
        // CHARACTERS and has a multi-byte character straddling the boundary.
        let names = ["CAFÉ MÜNCHEN GESELLSCHAFT MBH", "ÅÄÖ ÅÄÖ ÅÄÖ ÅÄÖ ÅÄÖ ÅÄÖ ÅÄÖ", "日本橋三越本店のオンラインストアの定期購読サービス"];
        for name in names {
            let clipped = clip(name, 22);
            assert_eq!(clipped.chars().count(), name.chars().count().min(22), "{name} clips by CHARACTERS");
            assert!(name.starts_with(&clipped), "{name} keeps its prefix");
        }
        // The point of the guard, asserted rather than assumed: for at least one of these, byte 22
        // lands INSIDE a character — so `&name[..22]`, which this replaced, would have panicked in
        // the renderer while the analysis behind it was perfectly correct.
        assert!(names.iter().any(|n| !n.is_char_boundary(22)), "no fixture straddles byte 22, so this proves nothing");
        assert_eq!(clip("short", 22), "short", "anything shorter is untouched");
        assert_eq!(clip("", 22), "");
    }
